import { Avatar } from '@refy-design/web';
import { NavCard } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof NavCard>,
    'title' | 'description' | 'leading' | 'meta'
  > = {
    title: 'Example team',
    description: 'example.com · Refy Pro · 4 members',
    leading: <Avatar initials="GE" size="lg" />,
    meta: <span>Admin</span>,
  };
  const [selected, setSelected] = useState(false);
  return (
    <div>
      <NavCard {...args} current={selected} onClick={() => setSelected(true)} />
      <p role="status">
        {selected
          ? 'Example team selected in this example.'
          : 'Select the team to try it.'}
      </p>
    </div>
  );
}

